import numpy as np

def f_nested(x, n):
    """
    Compute f_n(x) where:
    f_0(x) = x^2 - x
    f_k(x) = |f_{k-1}(x) - 1| for k >= 1
    This gives n nested absolute values.
    """
    val = x**2 - x
    val = abs(val)  # First absolute value
    for i in range(1, n):
        val = abs(val - 1)
    return val

# Test the function
print("Testing f_nested:")
print(f"f_1(3) = {f_nested(3, 1)}")  # Should be |9-3| = 6
print(f"f_2(3) = {f_nested(3, 2)}")  # Should be |6-1| = 5
print(f"f_3(3) = {f_nested(3, 3)}")  # Should be |5-1| = 4

# Define RHS
def rhs(x):
    return x**2 - 2*x - 14

# Define the equation: f_11(x) - rhs(x) = 0
def equation(x):
    return f_nested(x, 11) - rhs(x)

# Search for solutions
print("\nSearching for solutions...")
x_vals = np.linspace(-20, 25, 45001)  # Fine grid
y_vals = equation(x_vals)

# Find sign changes
sign_changes = []
for i in range(len(x_vals)-1):
    if y_vals[i] == 0:
        sign_changes.append(x_vals[i])
    elif y_vals[i] * y_vals[i+1] < 0:
        sign_changes.append((x_vals[i], x_vals[i+1]))

print(f"Sign changes found at: {sign_changes}")

# Refine solutions using bisection
def find_root(a, b, tol=1e-10):
    for _ in range(100):
        mid = (a + b) / 2
        if equation(a) * equation(mid) <= 0:
            b = mid
        else:
            a = mid
        if b - a < tol:
            return mid
    return (a + b) / 2

roots = []
for sc in sign_changes:
    if isinstance(sc, tuple):
        root = find_root(sc[0], sc[1])
        roots.append(root)
    else:
        roots.append(sc)

print(f"\nRefined roots: {roots}")
for r in roots:
    print(f"x = {r:.10f}, f_11(x) = {f_nested(r, 11):.10f}, rhs(x) = {rhs(r):.10f}")
